var o=`0428-raggmunk`;var n=`world-0428`;var i=`SE`;var a=`northern-europe`;var r=4;var s=38;var l={en:`Raggmunk`,ua:`Раґмунки`};var u={en:`A traditional dish from Sweden, centered on potato, all-purpose flour, chicken egg, whole cow milk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Швеція. Основні складники: картопля, пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:8,i:[[`potato`,650,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`all-purpose-flour`,90,`g`],[`chicken-egg`,1,`pcs`],[`whole-cow-milk`,200,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`unsalted-butter`,65,`g`]]},{en:`Simmer the lingonberries and sugar into a quick tart jam to serve with the potato pancakes.`,ua:`Коротко уваріть брусницю з цукром у кислуватий джем і подавайте з картопляними млинцями.`,t:[`sauteing`,`reducing-sauce`],m:8,i:[[`lingonberry`,130,`g`],[`white-granulated-sugar`,35,`g`]]}];var d={slug:o,id:n,country:`SE`,region:a,servings:4,minutes:38,title:l,text:u,steps:g};export{i as country,d as default,n as id,s as minutes,a as region,r as servings,o as slug,g as steps,u as text,l as title};